const BY_NAME = new Map(GENERATED_TOOL_COMPLETION_CONTRACTS.map((entry) => [entry.toolName, entry]));

/** public Tool 执行前必须命中唯一 completion contract。 */
export function generatedToolCompletionContract(name: string): GeneratedToolCompletionContract | undefined {
  return BY_NAME.get(name);
}
